// Helpers for checks that scan source *code* for a forbidden token (a banned
// API, an impure import, a DOM specific). Such a check must see code, not
// prose: a comment or a doc-string that merely *names* `chrome.storage` or
// `fetch(` is describing the code, not doing it, and matching it is a false
// positive that fails the build over an English sentence. Strip comments first.

// A `/` opens a regex literal only where a value may begin. After a value - 
// an identifier, a number, a closing `)` or `]` - it is division. The keywords
// are the identifiers that are not values, so the `/` after them opens a regex.
const VALUE_END = /[\w$)\]]$/;
const NOT_A_VALUE = /\b(return|typeof|instanceof|in|of|new|delete|void|case|do|else|yield|await)$/;
function opensRegex(code) {
  const before = code.replace(/\s+$/, '');
  if (before === '') return true;
  if (!VALUE_END.test(before)) return true;
  return NOT_A_VALUE.test(before);
}

// Return `source` with its JS/TS comments removed, leaving everything else —
// including string, template and regex literals - byte-for-byte intact.
// Literal-aware on purpose: a `//` inside "https://…" is not a comment, and
// dropping the rest of that line would corrupt real code (and could hide a
// genuine violation that follows on the same line). The same holds inside a
// regex, whose `"`, `'` and `` ` `` are pattern characters - reading one as a
// string's opening quote puts the scanner in string state for the rest of the
// file, where every later comment survives and every later string reads as code.
// Newlines inside block comments are kept so line numbers don't shift.
export function stripComments(source) {
  let out = '';
  let state = 'code'; // code | line | block | sq | dq | tpl | re | reClass
  // One frame per `${}` hole still open, innermost last, each holding the brace
  // depth reached inside it. A hole holds code, and that code may open a template
  // of its own, so the enclosing template is a place to return to rather than a
  // flag: without the stack the inner literal's backtick closed the outer one and
  // every character after it read inside-out.
  const holes = [];
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    const c2 = source[i + 1];
    if (state === 'code') {
      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
      if (c === '/' && opensRegex(out)) state = 're';
      else if (c === "'") state = 'sq';
      else if (c === '"') state = 'dq';
      else if (c === '`') state = 'tpl';
      else if (holes.length && c === '{') holes[holes.length - 1].depth++;
      else if (holes.length && c === '}') {
        if (holes[holes.length - 1].depth === 0) { holes.pop(); state = 'tpl'; }
        else holes[holes.length - 1].depth--;
      }
      out += c;
    } else if (state === 're' || state === 'reClass') {
      // Inside a regex literal. A `/` inside a character class is a literal
      // slash, not the closing delimiter, so the class is tracked as its own
      // state rather than guessed at.
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if (c === '\n') state = 'code'; // an unterminated regex was a division after all
      else if (state === 're' && c === '[') state = 'reClass';
      else if (state === 'reClass' && c === ']') state = 're';
      else if (state === 're' && c === '/') state = 'code';
    } else if (state === 'line') {
      if (c === '\n') { state = 'code'; out += c; }
    } else if (state === 'block') {
      if (c === '*' && c2 === '/') { state = 'code'; i++; }
      else if (c === '\n') out += c;
    } else {
      // Inside a string/template literal: copy through until the matching quote,
      // honoring backslash escapes so an escaped quote doesn't end it early.
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if (state === 'tpl' && c === '$' && c2 === '{') {
        out += c2; i++;
        holes.push({ depth: 0 });
        state = 'code';
      } else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
        state = 'code';
      }
    }
  }
  return out;
}

// The extensions whose comments `stripComments` actually models. A file outside
// this set is never called comments-only: the parser cannot see its comments, so
// "nothing but comments changed" is a claim it has no grounds for, and answering
// "no" is the end that fails safe for both callers below.
export const COMMENT_CHECKABLE = new Set([
  '.mjs', '.cjs', '.js', '.jsx', '.ts', '.tsx', '.c', '.h', '.cc', '.cpp', '.hpp',
  '.java', '.go', '.swift', '.kt', '.dart', '.rs', '.cs', '.scss', '.css',
]);

// Did a change to `file` touch only its comments? `before`/`after` are the file's
// two contents, null where it was added or deleted — neither of which is a
// comment-only change, whatever the other side holds.
//
// Indentation and blank lines are ignored, so a whitespace-only edit inside a
// template literal reads as comments-only; in a language whose indentation is
// semantic the extension set above has already answered no.
//
// Its callers grant a PERMISSION on the answer — may this run land its own pull
// request unreviewed, may it have touched this file at all — which is why the safe
// end is "no" and why the answer lives here rather than in each of them.
export function commentOnly(file, before, after) {
  if (before == null || after == null) return false;
  const dot = file.lastIndexOf('.');
  const ext = dot === -1 ? '' : file.slice(dot).toLowerCase();
  if (!COMMENT_CHECKABLE.has(ext)) return false;
  const meat = (text) => stripComments(text).split('\n').map((l) => l.trim()).filter((l) => l !== '').join('\n');
  return meat(before) === meat(after);
}

import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';
import { classificationLine, classesIn } from '../../../shared/engine/checks/helpers/session-transcript.mjs';

// The testable half of RULES.md's "Put the `Comment class:` line on its own
// line": the classifier reads the WHOLE classification line and adds EVERY class
// token it finds (`classesIn()` matches globally), so the natural-sounding
//     Comment class: other — not a correction, feature request, or process-change
// declares all four classes, not `other`. The stray `feature` then arms
// `feature-requirements-first` BLOCKING against whatever commits the branch
// carries, even when the session never touched a product feature.
//
// This asserts the MANDATED FORM, not the author's intent. The prose tells the
// agent to write the class alone and put any explanation on the next line, so
// the line either is that or it is not — a question every character of it
// answers. An earlier draft chased intent instead, firing only on a class token
// that followed a negation word from a hand-picked list ("not", "never",
// "besides", …). That is unbounded in the wrong direction: the harm comes from a
// class token being PRESENT, and prose smuggles them in without negating
// anything. Probed against the real helper, that draft stayed silent on
//     Comment class: other — unrelated to any feature request      (declares feature)
//     Comment class: other, setting the feature question aside     (declares feature)
//     Comment class: correction | feature | process-change | other (declares all four)
// — the last a verbatim paste of the menu out of the classifier's own prompt,
// i.e. the likeliest way this bug is reproduced, missed by the check named for
// it. Checking the form catches all three and needs no word list, because a
// conforming line has nowhere to hide a token.
//
// A genuinely mixed comment stays legal and stays silent: it names each part it
// really is, positively, on that one line (`Comment class: correction,
// process-change`). Whether four comma-separated classes are "honest" is exactly
// the intent judgment this rule refuses to make — the form is respected, so the
// classifier does what the line asked.
//
// ADVISORY, deliberately, where the underlying defect is blocking-grade: the
// transcript is append-only, so by the time this is observable the declaration
// cannot be retracted. A blocking finding could never converge — it would spend
// the session's Stop cycles on something no edit can fix, which is precisely the
// waste the lesson records. Its job is to name the cause the moment it appears
// so the session doesn't re-derive it from an unexplained
// `feature-requirements-first` failure.

// One class token, spelled as the classifier's own alternation spells it, so
// this check models what `classesIn()` sees rather than a second opinion of it.
const CLASS = String.raw`(?:correction|feature|process[\s-]change|other)`;
// The mandated form: class tokens joined by a declaration separator, nothing
// else. `|` is deliberately NOT a separator — it is how the prompt renders the
// menu, so pasting the menu verbatim fails this pattern rather than reading as
// a four-class declaration.
const CONFORMING_RE = new RegExp(String.raw`^\s*${CLASS}(?:\s*(?:,|&|\+|and)\s*${CLASS})*\s*\.?\s*$`, 'i');

const rule = {
  id: 'tldr/comment-class-menu',
  on_fail: 'advise',
  description: 'The `Comment class:` line must carry the class alone — every class token on it is declared, however the line phrases them',
  doc: '.claudinite/local/packs/tldr/RULES.md',
  scope: 'work',
  why: 'the classifier adds every class token on the classification line, so any explanation sharing that line declares the classes it mentions — a stray `feature` arms feature-requirements-first BLOCKING against the branch even when no product feature was touched',

  run(work) {
    // Only the latest owner turn is judged, for the same reason
    // comment-classification judges only that one: the transcript is
    // append-only, so an earlier turn's line was already reported at its own
    // Stop and can never converge.
    const turn = work.conversation().ownerTurns().last();
    if (!turn.exists) return [];
    const line = classificationLine(turn.reply());
    // No classification line at all is comment-classification's finding, not this one.
    if (!line) return [];

    // Everything after the `Comment class:` colon — the prefix cannot contain
    // one (the helper's pattern forbids it), so the first colon is the split.
    const declaration = line.slice(line.indexOf(':') + 1);
    if (CONFORMING_RE.test(declaration)) return [];

    const declared = [...classesIn(declaration)].sort();
    // A line naming no class at all is unclassified — comment-classification's
    // finding, not this one.
    if (!declared.length) return [];

    const arms = declared.includes('feature')
      ? ', including `feature`, which arms `feature-requirements-first` BLOCKING against this branch'
      : '';

    return [finding(rule, {
      file: '(conversation)',
      what: `the \`Comment class:\` line carries more than the class it means, so the classifier reads it as declaring ${declared.map((c) => `\`${c}\``).join(', ')}${arms}`,
      fix: 'write the class alone on its own line — `Comment class: other` — and put any explanation on the NEXT line; a genuinely mixed comment names each part it really is, comma-separated, on that one line. The transcript is append-only, so re-declaring cleanly on a later line does not override this one — do not retry, and expect the declared classes\' rules to fire on this branch',
    })];
  },
};

export default rule;

import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';

// A VENDORED workflow under `.github/workflows/` carries this repo's one
// deliberate delta over its canon stub: a step that aligns the repo-root
// package.json to a version the pipeline just bumped. It is load-bearing — the
// release config only bumps `manifest_path` and `package_json_path`, so without
// it the root file falls behind and both the `sharedConstants` version entry in
// .claudinite-checks.json and `cer/version-sync` go BLOCKING.
//
// WHICH FILE CARRIES IT MOVED with the chrome-extension pack's release-model
// overhaul (2026-08-21): the only automated, unattended version-write left in
// the pipeline is the deliberate minor/major dispatch
// (`chrome-extension-bump-version.yml`) — the routine patch bump that used to
// run inside the daily workflow's own `bump` job now belongs to the PR that
// touches a shipped file (`cer/version-bumped`), with a human in the loop who
// `cer/version-sync` will stop just as loudly if they forget the root file by
// hand. `chrome-extension-daily-release.yml` no longer bumps anything at all —
// it only checks whether the version already on `main` has shipped — so it is
// safe to take as a pure, un-diverged stub copy again.
//
// The delta is fragile in a specific, repeating way: the pack's
// `chrome-release-vendoring` migration MATERIALIZES this path — an unconditional
// verbatim overwrite from the stub, with no per-repo exemption seam (unlike a
// check finding, which .claudinite-checks.json can `accept`). Baselining
// re-attempts that write every cycle, so any agent that lands the withheld file
// mechanically deletes the step and silently re-opens the drift #241 closed.
// Issue #245 is the open decision on the real fix (teach release.config the root
// file, or give materialize an extension point); until it lands, this check is
// what makes the deletion loud instead of silent. When #245 resolves, delete
// this rule with the step.
//
// It keys on the BEHAVIOUR, not the step's label: the align step is the only
// place the workflow names the repo-root `package.json` as a literal file, since
// the stub reaches the two release-config paths through
// `${{ steps.cfg.outputs.* }}` only. So renaming or rewording the step keeps
// this silent, and only actually dropping the root-file write fires it.
const WORKFLOW = '.github/workflows/chrome-extension-bump-version.yml';

// The quoted literal the align step's inline node script reads and writes.
const ROOT_PACKAGE_JSON = /(["'])package\.json\1/;

const rule = {
  id: 'tldr/release-root-version-align',
  on_fail: 'block',
  description: "The daily-release workflow must keep aligning the repo-root package.json to the bumped version — it is this repo's local delta over the vendored stub",
  doc: '.claudinite/local/packs/tldr/RULES.md',
  scope: 'world',
  why: 'the release config bumps only the manifest and extension package.json, so without this step the repo-root package.json falls behind after every daily release and the version sharedConstants entry plus cer/version-sync both go BLOCKING (#241, #245)',

  run(ctx) {
    const text = ctx.read(WORKFLOW);
    // A missing file is `cer/release-workflows`'s finding, not this one.
    if (text === null) return [];
    if (ROOT_PACKAGE_JSON.test(text)) return [];

    return [finding(rule, {
      file: WORKFLOW,
      what: 'the bump job no longer writes the repo-root package.json — the "Align the root package.json to the bumped version" step is gone, so the next daily release will bump only the two release-config paths',
      fix: `restore the step from commit 2529b63 (PR #241) — it replaces the single \`"version": "X.Y.Z"\` token in the root package.json with \`steps.bump.outputs.version\` before the push. If it vanished after a baselining cycle, the chrome-release-vendoring materialize overwrote this file with the canon stub: re-apply the step rather than accepting the stub, and say so on #245`,
    })];
  },
};

export default rule;

import commentClassMenu from './comment-class-menu.mjs';
import releaseRootVersionAlign from './release-root-version-align.mjs';

// TLDR's own pack: the short, always-on repo-level lessons that aren't a canon
// rule and have no home in the mounted canon.
export default {
  id: 'tldr',
  ruleRoutingGuidance: {
    belongs: "TLDR's repo-level lessons — which file is authoritative, which direction a fix goes, release-pipeline gotchas",
    excludes: 'general software-engineering practice and portable procedure — those live in the vendored Claudinite canon',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [releaseRootVersionAlign],
  workRules: [commentClassMenu],
};

